import{_ as l,l as n,o as e,c as i,v as t,p as o,x as r,d as E,i as S,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"内建自测 BIST","description":"","frontmatter":{"title":"内建自测 BIST","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bist.md","filePath":"cs/bist.md","lastUpdated":1789023840000}'),A={name:"cs/bist.md"};function B(c,a,h,T,p,I){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="内建自测-bist" tabindex="-1">内建自测 BIST <a class="header-anchor" href="#内建自测-bist" aria-label="Permalink to &quot;内建自测 BIST&quot;">​</a></h1><div class="epigraph"><p>ATE 带宽和向量存储有限；片上用伪随机图案生成器刺激扫描链或存储器，压缩响应成签名，上电或现场也能自检。</p><footer>—— 据 Bushnell and Agrawal, Essentials of Electronic Testing；IEEE Std 1149.1；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/dft-scan-chain">上一课</a>把 FF 串成链，向量仍常来自片外 ATE。大芯片扫描数据量与引脚速率成为测试成本。缺口是 <strong>BIST</strong>：图案生成（LFSR）与响应压缩（MISR）放进硅里，ATE 只启动并读签名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逻辑 BIST：LFSR 灌扫描链，若干捕获周期，MISR 压输出。存储器 BIST：对 SRAM/DRAM PHY 旁的阵列走 March 算法，覆盖固定与转换故障。缺口不是再解释扫描 MUX，而是<strong>片上控制器</strong>与签名黄金值。随机图案对随机逻辑覆盖尚可，对规则算术可能要混合确定向量。</p><p>现场自检（上电、高可靠系统）让 BIST 超出工厂 ATE。航空与汽车安全标准会要求，本课点名不背条款。</p><h3 id="签名通过不是「无故障」" tabindex="-1">签名通过不是「无故障」 <a class="header-anchor" href="#签名通过不是「无故障」" aria-label="Permalink to &quot;签名通过不是「无故障」&quot;">​</a></h3><p>压缩有别名：两个响应可能同一签名。LFSR 多项式与 MISR 宽度降低别名概率，不是零。把 BIST 绿勾当成形式证明，与 LEC 课的警告同类。</p><p><span class="marginnote">Bushnell/Agrawal 专章 BIST。存储器 March 测试是工业常规。CA:AQA 把可靠性与检测作为系统问题。本课不写具体 LFSR 抽头表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LBIST：测试时钟下运行 \\(N\\) 周期，比较 MISR。MBIST：地址计数器 + 数据背景（5/A、棋盘）。与 JTAG：TAP 指令启动 BIST、读状态。与<a href="/cs/clock-gating-dvfs">时钟门控</a>：BIST 模式强制时钟开。功耗：伪随机高翻转，须降速或分块跑。</p>',11)),(e(),o(d,null,{default:r(()=>[S(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LFSR%5B%22LFSR%20%E5%9B%BE%E6%A1%88%22%5D%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%20%2F%20%E9%98%B5%E5%88%97%22%5D%0A%20%20SCAN%20--%3E%20MISR%5B%22%E5%93%8D%E5%BA%94%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20MISR%20--%3E%20SIG%5B%22%E7%AD%BE%E5%90%8D%E6%AF%94%E8%BE%83%22%5D%0A%20%20SIG%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BD%AF%E9%94%99%E8%AF%AF%E4%B8%8D%E6%98%AF%E5%88%B6%E9%80%A0%E7%BC%BA%E9%99%B7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>DRAM 后面单元有自己的维修与 BIST，与逻辑 BIST 分家。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课软错误是运行期辐射翻转，不是制造 stuck-at；BIST 上电能抓部分硬缺陷，抓不住随机位翻转——那要 ECC。老化可能让时序边沿在现场失败，BIST 定期跑可当健康检查，覆盖仍有限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把模拟环路 BIST（ADC）写完，不讨论加密密钥是否被 BIST 路径泄漏（安全课另开）。不把软件 memtest 当 MBIST。</p><p>后课默认：BIST 用片上 LFSR/MISR 或 March 降 ATE 成本；签名有别名；软错误要另一套。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扫描解决可控可观；BIST 把向量发生与压缩搬进芯片。</li><li>逻辑用 LFSR/MISR，存储器用 March。</li><li>通过 ≠ 无故障；现场可复用。</li><li>出处：Bushnell and Agrawal；IEEE 1149.1；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const m=l(A,[["render",B]]);export{u as __pageData,m as default};
